// Variant: Light-Pink-Fives & Orange (3 Suits). 3 players, our_player_index=1.


namespace {

std::vector<std::pair<hanabi::PerformAction, hanabi::Action>>
all_candidate_clues(const hanabi::Game& g) {
  const hanabi::State& s = g.state;
  std::vector<std::pair<hanabi::PerformAction, hanabi::Action>> out;
  for (int t = 0; t < s.num_players; ++t) {
    if (t == s.our_player_index) continue;
    for (const hanabi::Clue& c : s.all_valid_clues(t)) {
      hanabi::PerformAction pf =
          c.kind == hanabi::ClueKind::COLOUR
              ? hanabi::PerformAction{hanabi::PerformColour{c.target, c.value}}
              : hanabi::PerformAction{hanabi::PerformRank{c.target, c.value}};
      out.emplace_back(
          pf, hanabi::Action{hanabi::ClueAction{
                  s.our_player_index, t,
                  s.clue_touched(s.hands[t], c.kind, c.value), c.base()}});
    }
  }
  return out;
}

}  // namespace

